INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (1, 'soto-bangkong', 'Soto Bangkong', 1, 'Jl. Brigjen Katamso No. 2C, Karangkebagusan, Semarang Selatan', 15000, 4.6, 'Soto ayam legendaris yang sudah berjualan sejak 1950-an. Kuah beningnya pekat, isinya ayam suwir, soun, dan kentang goreng; paling pas disantap hangat dengan sate telur puyuh di pinggirnya.', '/images/tempat/soto-ayam.jpg', -6.9942579, 110.4323944, '07.00–21.00', TRUE, 'node/12143456101', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (2, 'nasi-goreng-babat-pak-karmin', 'Nasi Goreng Babat Pak Karmin Mberok', 1, 'Jl. Pemuda No. 2, Dadapsari, Semarang Utara', 25000, 4.7, 'Nasi goreng babat yang dimasak di atas tungku arang, memberi aroma smokey yang khas. Porsinya jumbo, babatnya empuk, dan sambalnya pedas mantap. Siap antre, karena hampir selalu ramai.', '/images/tempat/nasi-goreng.jpg', -6.9691666, 110.425055, '08.00–22.30', TRUE, 'node/8238986811', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (3, 'tahu-gimbal-mas-rendra', 'Tahu Gimbal Mas Rendra', 1, 'Kawasan Randusari, Semarang Selatan', 15000, 4.5, 'Tahu goreng, lontong, kol, dan gimbal udang disiram bumbu kacang yang legit. Tambahkan petis dan kecap sesuai selera — rasanya gurih, manis, dan sedikit asam segar.', '/images/tempat/tahu-gimbal.jpg', -6.991122, 110.4236163, '10.00–21.00', FALSE, 'node/10117045460', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (4, 'swieke-lumpia-koh-hoo', 'Swieke & Lumpia Koh Hoo', 1, 'Jl. Letjen Suprapto, Semarang Tengah', 30000, 4.4, 'Dua ikon Semarang dalam satu meja: lumpia rebung yang digoreng renyah dan swieke (kodok) dengan bumbu kental. Tempat sederhana, resepnya tetap dijaga dari generasi ke generasi.', '/images/tempat/lumpia.jpg', -6.989838, 110.4287792, '09.00–21.00', FALSE, 'node/11815637135', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (5, 'bakmi-jawa-pak-gareng', 'Bakmi Jawa Pak Gareng', 1, 'Jl. Wotgandul Dalam No. 177, Gabahan, Semarang Tengah', 20000, 4.6, 'Bakmi jawa dimasak satu per satu di wajan besi dengan arang. Kuah kaldunya manis-gurih, telurnya setengah matang, dan suasananya masih sangat tradisional. Cocok untuk makan malam.', '/images/tempat/bakmi-jawa.jpg', -6.9804337, 110.4230297, '17.00–23.00', FALSE, 'node/4520736289', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (6, 'asem-asem-koh-liem', 'Asem-Asem Koh Liem', 1, 'Jl. Karanganyar No. 28, Gabahan, Semarang Tengah', 25000, 4.6, 'Asem-asem daging sapi dengan kuah asam yang menyegarkan, dimasak ala rumahan sejak lama. Dagingnya empuk dan bumbunya meresap; pendampingnya nasi hangat dan sambal terasi.', '/images/tempat/asem-asem.jpg', -6.9812558, 110.4267679, '07.00–17.00', FALSE, 'node/7071652386', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
