INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (8, 'nasi-ayam-mbok-ru', 'Nasi Ayam Mbok Ru', 1, 'Jl. Sebandaran No. 31, Gabahan, Semarang Tengah', 18000, 4.4, 'Nasi ayam kampung dengan kuah kaldur bening, kecap manis, dan sambal rawit. Warungnya kecil dan sederhana, tapi rasa rumahan inilah yang bikin pelanggan kembali lagi.', '/images/tempat/nasi-ayam.jpg', -6.9789944, 110.4267634, '07.00–20.00', FALSE, 'node/12915915139', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
