INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (11, 'moment-coffee-and-space', 'Moment Coffee & Space', 2, 'Jl. Rajabasa No. 82–83, Bendungan, Gajahmungkur', 35000, 4.5, 'Rumah dua lantai yang diubah menjadi kafe dengan banyak sudut untuk duduk lama. Menunya kopi, teh, pasta, dan kue; suasananya tenang di sore hari.', '/images/tempat/es-kopi-susu.jpg', -7.0206882, 110.4124746, '09.00–24.00', FALSE, 'node/7075294785', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
