INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (15, 'marabunta', 'Marabunta', 3, 'Jl. Cendrawasih No. 23, Miroto, Semarang Tengah', 75000, 4.6, 'Restoran dengan interior hangat dan menu gabungan Indonesia–internasional. Cocok untuk makan malam berdua atau perayaan kecil; porsi besar dan presentasinya rapi. Buka sampai dini hari.', '/images/tempat/ikan-bakar.jpg', -6.9669042, 110.4299781, '10.00–02.00', TRUE, 'node/12139183401', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (16, 'sakapatat-beer-garden', 'Sakapatat Beer Garden & Resto', 3, 'Jl. Diponegoro No. 24, Tegalsari, Candisari', 85000, 4.5, 'Resto dan beer garden dengan taman luas dan panggung musik. Menunya burger, steak, dan makanan bar; ramai saat akhir pekan. Tempat favorit untuk nonton bareng.', '/images/tempat/burger.jpg', -7.00126, 110.4175868, '11.00–01.00', FALSE, 'node/4431964389', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (17, 'ellenas-kitchen', 'Ellena''s Kitchen', 3, 'Jl. Tirto Agung No. 67D, Pedalangan, Banyumanik', 60000, 4.6, 'Rumah makan keluarga dengan menu Indonesia, seafood, dan mie. Porsinya besar, harganya masuk akal, dan tempatnya nyaman untuk makan siang bersama keluarga.', '/images/tempat/seafood.jpg', -7.0587328, 110.4281396, '10.00–22.00', FALSE, 'node/6749823786', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (18, 'converso-coffee-eatery', 'Converso Coffee & Eatery', 3, 'Jl. Durian Raya No. 52C, Srondol, Banyumanik', 55000, 4.5, 'Kafe-eatery dengan menu pizza, fish and chips, dan kopi. Ruangannya luas dan banyak meja besar, jadi sering dipakai untuk kerja kelompok atau arisan.', '/images/tempat/pizza.jpg', -7.0617033, 110.4188805, '11.00–23.00', FALSE, 'node/7071652387', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (19, 'the-tavern-semarang', 'The Tavern', 3, 'Jl. Rinjani/Sumbing No. 1, Bendungan, Gajahmungkur', 95000, 4.4, 'Steak house dan bar dengan suasana remang dan musik live. Potongan dagingnya dimasak sesuai pesanan; ada juga pizza untuk yang tidak makan steak. Buka sore hingga tengah malam.', '/images/tempat/steak.jpg', -7.0038481, 110.4092561, '16.00–24.00', FALSE, 'node/6176000085', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (20, 'pringsewu-kota-lama', 'Pringsewu Kota Lama', 3, 'Kawasan Kota Lama, Semarang Utara', 50000, 4.4, 'Rumah makan Indonesia dengan banyak pilihan lauk nusantara, dari rendang sampai ikan bakar. Tempatnya luas dan sering jadi pilihan makan siang rombongan setelah berkeliling Kota Lama.', '/images/tempat/nasi-padang.jpg', -6.9692719, 110.4277055, '08.00–22.00', FALSE, 'node/3476354579', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (21, 'tahu-petis-mirasa', 'Tahu Petis Mirasa', 4, 'Kawasan Srondol, Banyumanik', 10000, 4.3, 'Tahu goreng hangat yang dibelah dan diisi petis udang kental. Camilan sederhana khas Semarang yang paling enak dimakan langsung di tempat, ditemani cabai rawit.', '/images/tempat/tahu-petis.jpg', -7.0714848, 110.4296935, '10.00–20.00', FALSE, 'way/997439077', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (22, 'richese-factory', 'Richese Factory', 4, 'Jl. Jenderal Sudirman No. 170, Gisikdrono, Semarang Barat', 25000, 4.3, 'Kedai ayam crispy dengan bumbu kering dan saus pilihan. Porsinya pas untuk makan siang cepat, tersedia paket nasi dan minuman. Tempatnya kecil, banyak yang memilih bawa pulang.', '/images/tempat/fried-chicken.jpg', -6.981265, 110.3981374, '10.00–22.00', FALSE, 'node/5030541326', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (23, 'mcdonalds-pamularsih', 'McDonald''s Pamularsih', 4, 'Jl. Pamularsih, Bojongsalaman, Semarang Barat', 30000, 4.4, 'Gerai cepat saji dengan drive-thru, area bermain, dan tempat parkir luas. Pilihan aman untuk sarapan cepat atau makan malam setelah perjalanan jauh.', '/images/tempat/french-fries.jpg', -6.988789, 110.3943846, '07.00–24.00', FALSE, 'way/581030886', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';
INSERT INTO tempat (id, slug, nama, kategori_id, alamat, harga, rating, deskripsi, foto_url, lat, lng, jam_buka, populer, osm_id, sumber, status) VALUES (24, 'wedang-es-puter-pak-kirman', 'Aneka Wedang & Es Puter Pak Kirman', 4, 'Jl. M.T. Haryono No. 406, Rejosari, Semarang Timur', 12000, 4.7, 'Gerobak legendaris yang buka malam: es puter santan buatan tangan dengan roti, kacang, dan tape. Ada juga wedang ronde dan teh hangat untuk malam yang dingin.', '/images/tempat/es-puter.jpg', -6.9824882, 110.4314778, '19.00–24.00', TRUE, 'node/8237795118', 'kurasi', 'approved') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, nama = EXCLUDED.nama, kategori_id = EXCLUDED.kategori_id, alamat = EXCLUDED.alamat, harga = EXCLUDED.harga, rating = EXCLUDED.rating, deskripsi = EXCLUDED.deskripsi, foto_url = EXCLUDED.foto_url, lat = EXCLUDED.lat, lng = EXCLUDED.lng, jam_buka = EXCLUDED.jam_buka, populer = EXCLUDED.populer, status = 'approved';

